sys_ux_data_broker_transform.script:
function transform(input) {
    var output = [];

    try {
        // Aggregate publisher counts
        var gr = new GlideAggregate('cmdb_sam_sw_discovery_model');
        gr.groupBy('publisher'); // Group by the publisher field
        gr.addAggregate('COUNT'); // Count records for each publisher
        gr.orderByAggregate('COUNT'); // Sort by publisher count in descending order
        gr.query();

        var orderIndex = 1; // Initialize order counter

        // Check if no records were returned
        if (!gr.hasNext()) {
            gs.info("No records found in cmdb_sam_sw_discovery_model.");
        }

        // Loop through the records
        while (gr.next()) {
            var publisherID = gr.getDisplayValue('publisher'); // Get publisher display value
            var publisherCount = gr.getAggregate('COUNT'); // Get count of records for this publisher

            // Log publisher ID and count for debugging
            gs.info("Publisher: " + publisherID + " | Count: " + publisherCount);

            // Push each publisher as an item in the schema format
            output.push({
                checked: false,
                order: orderIndex, // Increment order for each item
                itemId: "checkbox_" + orderIndex,
                label: publisherID + " (Count: " + publisherCount + ")", // Customize label
                hasLink: true,

            });

            orderIndex++; // Increment order index
        }

        // If no data was found for publishers, log the result
        if (output.length === 0) {
            gs.info("No publishers found after aggregation.");
        }

        // Log the transformed data for debugging
        gs.info("Transformed Data: " + JSON.stringify(output));

    } catch (e) {
        // Error handling and logging the error to the ServiceNow logs
        gs.error("Error in transform script: " + e.toString());
        return {
            error: e.toString() // Return error details for debugging
        };
    }

    // Return the transformed data
    return output;
}
